"""Parsing invoices from text."""
from invoices import Invoice


def _parse_line(line):
    client, due = line.split(",")
    return Invoice(client.strip(), int(due))


def parse_invoices(text):
    """Parse lines of 'client,due' into Invoice records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)


def client_names(invoices):
    """Return the distinct client values, in first-seen order."""
    names = []
    for x in invoices:
        if x.client not in names:
            names.append(x.client)
    return names

